-- ============================================================================
-- RP_17_classification_masters_seed.sql
-- Snapshot seed of the classification master tables in their CURRENT state
-- (as reset by RP_14/RP_15/RP_16 + manual activations on 2026-07-07):
--   RP_M_UNIT_TYPE, RP_M_VERTICAL, RP_M_UNIT, RP_M_DEPARTMENT, RP_M_ACTIVITY
--
-- IDs are preserved exactly (verticals = SOL ID, activities = Activity_ID,
-- departments = generated ID with CODE='<verticalId>_<excelDeptId>').
-- IS_ACTIVE flags are preserved as-is (0 = deactivated legacy rows kept for FK).
--
-- This replaces the master content wholesale. Children are deleted first to
-- respect FKs; rows that are still referenced by transactional data (requests,
-- routing, escalation) will block the DELETE — run RP_16's dependent-cleanup
-- first, or run this on a fresh schema.
--
-- Idempotent-ish: safe to re-run on an empty/reset masters set. Run as RP_OWNER.
-- ============================================================================
SET DEFINE OFF
SET SERVEROUTPUT ON
WHENEVER SQLERROR CONTINUE

PROMPT === Clearing existing classification masters (children first) ===
DELETE FROM RP_M_ACTIVITY;
DELETE FROM RP_M_DEPARTMENT;
UPDATE RP_M_UNIT SET PARENT_UNIT_ID = NULL;
DELETE FROM RP_M_UNIT;
DELETE FROM RP_M_VERTICAL;
DELETE FROM RP_M_UNIT_TYPE;
COMMIT;

PROMPT === Seeding classification masters (parents first) ===
PROMPT === RP_M_UNIT_TYPE ===
PROMPT === RP_M_VERTICAL ===
PROMPT === RP_M_UNIT ===
PROMPT === RP_M_DEPARTMENT ===
PROMPT === RP_M_ACTIVITY ===

COMMIT;

PROMPT === Verify ===
SELECT 'unit_types'  item, COUNT(*) n FROM RP_M_UNIT_TYPE
UNION ALL SELECT 'verticals',   COUNT(*) FROM RP_M_VERTICAL
UNION ALL SELECT 'units',       COUNT(*) FROM RP_M_UNIT
UNION ALL SELECT 'departments', COUNT(*) FROM RP_M_DEPARTMENT
UNION ALL SELECT 'activities',  COUNT(*) FROM RP_M_ACTIVITY;
